SELECT LOWER(COLUMN_NAME) AS column_name,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='repair_detail' ORDER BY ORDINAL_POSITION;
SELECT INDEX_NAME,SEQ_IN_INDEX,LOWER(COLUMN_NAME) AS column_name FROM information_schema.STATISTICS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='repair_detail' AND INDEX_NAME='PRIMARY' ORDER BY SEQ_IN_INDEX;SELECT LOWER(k.COLUMN_NAME) AS column_name,k.REFERENCED_TABLE_NAME,LOWER(k.REFERENCED_COLUMN_NAME) AS referenced_column_name,DELETE_RULE
FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r USING (CONSTRAINT_SCHEMA, CONSTRAINT_NAME, TABLE_NAME)
WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='repair_detail' ORDER BY COLUMN_NAME;

